namespace sv_8014729834ab41cea1abc645aad7dd8f.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Registered as Scoped so each SignalR circuit (user) gets its own instance.
/// </summary>
public class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    /// <summary>
    /// Raised whenever theme or accent color changes so all subscribers can re-render.
    /// </summary>
    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }
}

@using sv_8014729834ab41cea1abc645aad7dd8f.Services
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "❓"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@using sv_8014729834ab41cea1abc645aad7dd8f.Services
@inject ThemeService ThemeService
@implements IDisposable

<div class="theme-toggle px-3 py-2">
    <label class="form-label text-light mb-1" style="font-size: 0.85rem;">Theme</label>
    <select class="form-select form-select-sm"
            value="@ThemeService.CurrentTheme"
            @onchange="OnThemeChanged">
        @foreach (var theme in Enum.GetValues<Theme>())
        {
            <option value="@theme">@theme</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
        {
            ThemeService.SetTheme(theme);
        }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@using sv_8014729834ab41cea1abc645aad7dd8f.Services
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px; border-color: @ThemeService.AccentColor;">
    <div class="card-body">
        <h5 class="card-title">Theme Settings</h5>

        <div class="mb-3">
            <label class="form-label">Theme</label>
            <select class="form-select"
                    value="@ThemeService.CurrentTheme"
                    @onchange="OnThemeChanged">
                @foreach (var theme in Enum.GetValues<Theme>())
                {
                    <option value="@theme">@theme</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color"
                       class="form-control form-control-color"
                       value="@ThemeService.AccentColor"
                       @onchange="OnAccentChanged" />
                <span class="text-muted">@ThemeService.AccentColor</span>
            </div>
        </div>

        <div class="alert alert-info mb-0" style="border-color: @ThemeService.AccentColor;">
            Changes apply immediately to all components — check the header
            indicator and sidebar toggle.
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
        {
            ThemeService.SetTheme(theme);
        }
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        var color = e.Value?.ToString();
        if (!string.IsNullOrEmpty(color))
        {
            ThemeService.SetAccentColor(color);
        }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

